package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePeriod {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody PeriodRequest request, Out<PeriodInput> body, RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        if (request == null || request.name() == null || request.name().trim().isEmpty()) {
            throw new InvalidSheetException("A name is required");
        }
        LocalDate from = date(request.from(), "from");
        LocalDate to = date(request.to(), "to");
        if (to.isBefore(from)) {
            throw new InvalidSheetException("The to date must not be before the from date");
        }
        body.set(new PeriodInput(request.name().trim(), from, to, request.user()));
    }

    private static LocalDate date(String value, String field) throws InvalidSheetException {
        String text = value == null ? "" : value.trim();
        if (text.isEmpty()) {
            throw new InvalidSheetException("A " + field + " date is required");
        }
        try {
            return LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw new InvalidSheetException("Not a date: " + text);
        }
    }
}
# POST /api/sheets/{sheetId}/periods/{periodName}/close — close a period (body: {user}), fixing its
# due-total and each person's due-total in it as they are now (the figures of the claims that count dated in it, skipping n/a); later rate
# changes do not alter it. Refused (400) when the sheet's permission matrix (perm-close; by default a
# clerk or a steward) does not allow the user's role, when the period is not on the sheet or is already closed;
# nothing is stored then. A closed period is recorded in the audit file as PERIOD_CLOSED.
validate:
  class: net.officefloor.hq.app.period.ValidateClose
  next: close
close:
  class: net.officefloor.hq.app.period.ClosePeriod
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.period.AuditPeriodClosed
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithClosedPeriod
  govern: [ transaction ]
# POST /api/sheets/{sheetId}/periods/{periodName}/reopen — reopen a closed period (body: {user}),
# dropping its fixed due-total so it totals its claims' current figures again. Refused (400) when the
# sheet's permission matrix (perm-reopen; by default a steward) does not allow the user's role, the period is not on the sheet or is not closed; nothing is
# stored then. A reopened period is recorded in the audit file as PERIOD_REOPENED.
validate:
  class: net.officefloor.hq.app.period.ValidateClose
  next: reopen
reopen:
  class: net.officefloor.hq.app.period.ReopenPeriod
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.period.AuditPeriodReopened
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithClosedPeriod
  govern: [ transaction ]
# GET /api/sheets/{sheetId}/periods — every period on the sheet, by from-date.
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriods
  govern: [ readonly-transaction ]
-- The sheet's periods: each named (unique on the sheet, ignoring case) and spanning from_date to
-- to_date inclusive; no two periods on a sheet overlap. Listed by from-date.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(255) NOT NULL,
    name      VARCHAR(255) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL
);
CREATE INDEX period_sheet ON period (sheet_id, from_date);
-- A closed period: its due-total is fixed at closed_total (the figures of the claims that counted in
-- it when it was closed, skipping n/a); no claim dated inside it may be added, edited or moved on.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(19, 2);
-- Each person's due-total in a closed period, fixed when the period was closed (the figures of their
-- claims that counted in it, skipping n/a). The period's closed_total is the sum of these. Dropped on
-- reopening; a person with no row here shows 0.00 for the closed period.
CREATE TABLE period_person_total (
    sheet_id    VARCHAR(255)   NOT NULL,
    period_name VARCHAR(255)   NOT NULL,
    person_id   BIGINT         NOT NULL,
    total       DECIMAL(19, 2) NOT NULL,
    PRIMARY KEY (sheet_id, period_name, person_id)
);
-- A claim's number is now text: the sheet-wide 1, 2, ... as before, or, while the sheet numbers by
-- period, <period name>-<n> (X-<n> for a claim in no period). A correction names it the same way.
ALTER TABLE claim ALTER COLUMN number VARCHAR(255);
ALTER TABLE claim ALTER COLUMN corrects VARCHAR(255);
-- The last number given in each per-period sequence on a sheet ('P:<period name>', or 'X' for claims
-- in no period). Locked while a number is taken, as claim_number is.
CREATE TABLE claim_period_number (
    sheet_id    VARCHAR(255) NOT NULL,
    sequence    VARCHAR(255) NOT NULL,
    last_number BIGINT NOT NULL,
    PRIMARY KEY (sheet_id, sequence)
);

