package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.Retirement;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;

/** The claim form's add, step by step, for a change that adds several claims at once (a paste). */
public final class ClaimAdding {
    private ClaimAdding() {
    }

    /** The claim form's rules on a claim typed for the person, before anything is stored: the claim as
     *  it would be stored. */
    public static ClaimInput check(String sheetId, Person person, ClaimRequest request, SheetStore sheets,
            PeriodStore periods, ClaimStore claims) throws InvalidSheetException {
        ClaimInput input = ValidateClaim.check(sheetId, request, sheets);
        CheckClaimPeriod.refuseClosed(periods, sheetId, input.date());
        Retirement.refuseClaimDate(person, input.date());
        CheckCorrection.refuseUnsettled(claims, sheetId, person.getId(), input);
        return input;
    }

    /** Stores the checked claim as a DRAFT and records it as CLAIM_ADDED, then how it moved the figures. */
    public static Claim add(ClaimInput input, Person person, ClaimStore store, SettingStore settings,
            ClaimLogStore log, RollupService rollups, Audit audit) {
        var before = rollups.snapshot(person.getSheetId());
        Claim claim = SaveClaimAdded.add(input, person, store, settings, log);
        AuditClaimAdded.record(input, person, claim, before, audit, rollups);
        return claim;
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Adds the claim, due by its date plus its person's own terms (else the terms of their grade in force on
 *  that date, else the sheet's terms in force then), fixed now, and logs it as DRAFT by the user at its due then. */
public class SaveClaimAdded {
    public void save(@Val ClaimInput input, @Val Person person, ClaimStore store, SettingStore settings,
            ClaimLogStore log, Out<Claim> claim) {
        claim.set(add(input, person, store, settings, log));
    }

    static Claim add(ClaimInput input, Person person, ClaimStore store, SettingStore settings, ClaimLogStore log) {
        int terms = termsOf(person, input.date(), settings);
        Claim added = store.add(person.getSheetId(), person.getId(), input.amount(), input.date(), input.note(),
                input.corrects(), input.date().plusDays(terms));
        log.record(added, input.user());
        return added;
    }

    /** The terms a claim of the person dated {@code date} is due by: their own, else their grade's in force
     *  on the date, else the sheet's then. */
    static int termsOf(Person person, java.time.LocalDate date, SettingStore settings) {
        return person.getTerms() != null ? person.getTerms()
                : settings.terms(person.getSheetId(), person.gradeOn(date), date);
    }
}
package net.officefloor.hq.app.paste;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimAdding;
import net.officefloor.hq.app.claim.ClaimLogStore;
import net.officefloor.hq.app.claim.ClaimStore;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Adds each pasted claim in order as the claim form would, a DRAFT recorded as CLAIM_ADDED. */
public class SavePasted {
    public void save(@Val PasteInput pasted, ClaimStore store,
            SettingStore settings, ClaimLogStore log, RollupService rollups, Audit audit, Out<PasteResult> result) {
        for (PastedClaim p : pasted.claims()) {
            ClaimAdding.add(p.claim(), p.person(), store, settings, log, rollups, audit);
        }
        result.set(new PasteResult(pasted.claims().size()));
    }
}
